```python
class Document:
    def __init__(self, title):
        self.title = title
        self.sections = {}
        self.collaborators = set()
        self.changes = {}

    def add_section(self, section_name, content):
        if section_name not in self.sections:
            self.sections[section_name] = {}
        self.sections[section_name].update(content)

    def remove_section(self, section_name):
        if section_name in self.sections:
            del self.sections[section_name]

    def add_collaborator(self, name):
        self.collaborators.add(name)

    def remove_collaborator(self, name):
        self.collaborators.discard(name)

    def track_change(self, section_name, new_content):
        if section_name in self.sections:
            self.changes[section_name] = new_content
        else:
            print("Section does not exist.")

    def get_changes(self):
        return self.changes

def create_document(title):
    return Document(title)
```

You can create a new document by calling `create_document("My Collaborative Document")` and then interact with it using the methods provided. For example:

```python
document = create_document("My Collaborative Document")
document.add_section("Introduction", "This is the introduction section.")
document.add_section("Body", "This is the body section.")
document.add_collaborator("John Doe")
document.add_collaborator("Jane Doe")

print(document.get_changes())
document.track_change("Introduction", "This is the updated introduction section.")
print(document.get_changes())
```

