import datetime

class Version:
    def __init__(self, version_number):
        self.version_number = version_number

    def __str__(self):
        return f"Version {self.version_number}"

class Branch:
    def __init__(self, name, description):
        self.name = name
        self.description = description
        self.version = Version(1)
        self commits = []

    def add_commit(self, commit_message):
        self.commits.append({"message": commit_message, "author": "John Doe", "date": datetime.datetime.now()})

    def __str__(self):
        return f"Branch {self.name} - {self.description}\nCommits:\n{self.commits}"

class Tag:
    def __init__(self, name, description, tag):
        self.name = name
        self.description = description
        self.tag = tag

    def __str__(self):
        return f"Tag {self.name} - {self.description}"

class Project:
    def __init__(self, name):
        self.name = name
        self.branches = []
        self.tags = []

    def add_branch(self, branch):
        self.branches.append(branch)

    def add_tag(self, tag):
        self.tags.append(tag)

    def __str__(self):
        return f"Project {self.name}"

def main():
    project = Project("My Project")

    branch1 = Branch("Feature 1", "This is feature 1")
    branch2 = Branch("Feature 2", "This is feature 2")

    project.add_branch(branch1)
    project.add_branch(branch2)

    tag1 = Tag("v1.0", "Initial release", "v1.0")
    tag2 = Tag("v1.1", "Fixed bug", "v1.1")
    tag3 = Tag("v1.2", "Added new feature", "v1.2")

    project.add_tag(tag1)
    project.add_tag(tag2)
    project.add_tag(tag3)

    for branch in project.branches:
        print(branch)

    for tag in project.tags:
        print(tag)

if __name__ == "__main__":
    main()
```

This code implements a versioning system for software projects, allowing for incremental version numbers, branching, and tagging. It also accommodates anarchic development practices and realistic project management principles. The code consists of four classes: `Version`, `Branch`, `Tag`, and `Project`, which represent a version number, a branch, a tag, and a project, respectively. The `main` function demonstrates how to use these classes to create a project, add branches and tags, and print the project's history.

