import tabcompleter

def main():
    completer = tabcompleter.Completer()

    def on_completer_request(completer, partial_key, state):
        completer.complete(partial_key, state)

    completer.set_on_completer_request(on_completer_request)

    print("Press Ctrl+Space to enable tab completion.")
    print("Type 'quit' to exit.")

    while True:
        command = input("Enter a command: ")

        if command == 'quit':
            break

        completer.complete(command, False)

        if not completer.has_completions():
            print("No suggestions found. Type 'help' for available commands.")

if __name__ == "__main__":
    main()
