package cpuset

import (
	"fmt"
	"os/exec"
)

// ForkCpuSet creates a forked cpuset environment
func ForkCpuSet() error {
	cmd := exec.Command("cpuset", "fork")
	output, err := cmd.CombinedOutput()
	if err != nil {
		return err
	}

	// We assume that the output is a byte slice containing the new cpuset
	// We decode it to a string and print it
	fmt.Println(string(output))
	return nil
}

func main() {
	if err := ForkCpuSet(); err != nil {
		fmt.Println(err)
	}
}
