import click
import jsonschema
from jsonschema import validate

@click.group()
def cli():
    """A simple JSON schema validation CLI."""
    pass

@cli.command()
@click.option('--input-file', type=click.Path(exists=True), help='Path to the input JSON file')
@click.option('--output-file', type=click.Path(exists=False), help='Path to the output JSON file')
def validate(input_file, output_file):
    """Validate a JSON file against a JSON schema."""
    schema = {
        "type": "object",
        "properties": {
            "name": {"type": "string"},
            "age": {"type": "integer"}
        },
        "required": ["name", "age"]
    }

    try:
        with open(input_file, "r") as f:
            data = json.load(f)

        validate(instance=data, schema=schema)
        if validate.is_valid():
            with open(output_file, "w") as f:
                json.dump(data, f, indent=4)
            click.echo("JSON file is valid")
        else:
            click.echo("JSON file is invalid")
    except FileNotFoundError:
        click.echo(f"File {input_file} not found")

@cli.command()
@click.option('--input-file', type=click.Path(exists=True), help='Path to the input JSON file')
@click.option('--output-file', type=click.Path(exists=False), help='Path to the output JSON file')
def create_schema(input_file, output_file):
    """Create a JSON schema for a JSON file."""
    schema = {
        "type": "object",
        "properties": {
            "name": {"type": "string"},
            "age": {"type": "integer"}
        },
        "required": ["name", "age"]
    }

    try:
        with open(input_file, "r") as f:
            data = json.load(f)

        validate(instance=data, schema=schema)
        if validate.is_valid():
            click.echo("JSON schema is valid")
        else:
            click.echo("JSON schema is invalid")
    except FileNotFoundError:
        click.echo(f"File {input_file} not found")

if __name__ == "__main__":
    cli()
```
